def construct():
    """
    Lightweight stochastic local search to build a small set B of non-negative integers
    such that all differences 1..n are covered for maximal n, while minimizing |B|^2/n.
    Returns a deduplicated, non-negative integer list (0 is included if not already).
    """
    import random, time

    # Evaluate how good a candidate B is: -(|B|^2 / n) where n is the largest integer
    # such that all 1..n are present as pairwise differences.
    def evaluate(B):
        if not B:
            return -1e9
        B = sorted(set(B))
        if B[0] < 0:
            return -1e9
        # compute all positive differences
        diffs = set()
        L = len(B)
        for i in range(L):
            bi = B[i]
            for j in range(i + 1, L):
                d = B[j] - bi
                if d > 0:
                    diffs.add(d)
        if 1 not in diffs:
            return -1e9  # invalid: must cover 1
        # largest n such that 1..n are all present
        n = 0
        while (n + 1) in diffs:
            n += 1
        # score: negative of (|B|^2 / n)
        return - (len(B) ** 2) / n

    # Initial population: few seeds with modest sizes
    random.seed(42)
    best_B = None
    best_score = -1e9

    # seed from small consecutive plus a few random points
    seeds = []
    for base in range(0, 15, 3):
        s = {base, base + 1, base + 2, base + 4}
        seeds.append(sorted(list(s)))
    for _ in range(6):
        seeds.append(sorted(set(random.randint(0, 40) for _ in range(random.randint(3, 6)))))

    # evaluate seeds
    for B in seeds:
        try:
            sc = evaluate(B)
        except Exception:
            sc = -1e9
        if sc > best_score:
            best_score, best_B = sc, B

    # Local search within a time budget
    t0 = time.time()
    time_budget = 0.95  # seconds
    while time.time() - t0 < time_budget:
        if best_B is None:
            # start from a small consecutive block
            cur = list(range(0, 6))
        else:
            cur = best_B.copy()

        # Mutation: occasionally add, remove, or tweak
        if random.random() < 0.6 and len(cur) < 12:
            x = random.randint(0, 60)
            if x not in cur:
                cur.append(x)
                cur.sort()
        else:
            if len(cur) > 2:
                idx = random.randrange(len(cur))
                cur.pop(idx)

        # Evaluate
        sc = evaluate(cur)
        if sc > best_score:
            best_score, best_B = sc, cur

    # Final cleanup: ensure non-negative and 0 included
    if best_B is None or len(best_B) == 0:
        best_B = [0, 1, 3, 6]
    best_B = sorted(set(best_B))
    if best_B[0] != 0:
        best_B = [0] + best_B

    return best_B

