def construct():
    """
    Stochastic restart local-search for compact difference-cover sets.
    Builds a set B of non-negative integers (0 included) such that differences cover 1..n
    for as large n as possible, while keeping |B| small. Uses bounded growth to avoid
    pathological expansion.
    """
    import time
    import random

    def coverage_n(B):
        if not B:
            return 0
        B = sorted(set(B))
        diffs = set()
        L = len(B)
        for i in range(L):
            bi = B[i]
            for j in range(i + 1, L):
                d = B[j] - bi
                if d > 0:
                    diffs.add(d)
        if 1 not in diffs:
            return 0
        n = 0
        while (n + 1) in diffs:
            n += 1
        return n

    def candidates_for_next_d(next_d, current):
        cur_set = set(current)
        cands = []
        for b in current:
            for cand in (b + next_d, b - next_d):
                if cand >= 0 and cand not in cur_set:
                    cands.append(cand)
        return sorted(set(cands))

    t0 = time.time()
    time_budget = 0.95

    best_B = [0, 1, 3, 6]  # seed with a small, spread set
    best_B = sorted(set(best_B))
    # Ensure 0 is present
    if best_B[0] != 0:
        best_B = [0] + best_B

    random.seed(42)

    while time.time() - t0 < time_budget:
        # Start from a random perturbation of best_B
        seed = best_B.copy()
        # slight shuffle via random swap to explore neighborhood
        if len(seed) >= 4:
            idxs = random.sample(range(len(seed)), k=min(2, len(seed)))
            for idx in idxs:
                delta = random.randint(-2, 2)
                if 0 <= seed[idx] + delta:
                    seed[idx] += delta
        B = sorted(set(seed))

        # Guarantee 0 is present
        if B[0] != 0:
            B = [0] + B

        # Local extension loop
        while time.time() - t0 < time_budget:
            n = coverage_n(B)
            next_d = n + 1
            if next_d <= 0:
                # try to force 1 coverage by adding a small element
                if 0 in B:
                    candidate = 1
                else:
                    candidate = 0
                if candidate not in B:
                    B.append(candidate)
                    B = sorted(set(B))
                    continue
                else:
                    break

            cand_list = candidates_for_next_d(next_d, B)
            if cand_list:
                # choose a random candidate among the smallest few to diversify
                x = cand_list[0]
                if x in B:
                    break
                B.append(x)
                B = sorted(set(B))
                continue

            # Fallback: bounded growth to avoid runaway max
            max_b = max(B)
            # try to place a new element not too far, starting near next_d
            placed = False
            for attempt in range(0, 1000):
                x = max(0, next_d + attempt // 3)
                if x not in B and x <= max_b + 2000:
                    B.append(x)
                    B = sorted(set(B))
                    placed = True
                    break
            if not placed:
                # if cannot place within bound, break to restart
                break

            # limit size to prevent explosion
            if len(B) > 2000:
                break

        # Evaluate and possibly adopt as best
        B = sorted(set(B))
        if 0 not in B:
            B = [0] + B
        cur_n = coverage_n(B)
        # keep best by maximizing n/|B| approximately; here we keep smallest |B| for same n
        if cur_n > 0:
            if best_B is None or (cur_n > coverage_n(best_B)) or (cur_n == coverage_n(best_B) and len(B) < len(best_B)):
                best_B = B

    # Final cleanup
    B = sorted(set(best_B))
    if 0 not in B:
        B = [0] + B
    # Deduplicate and trim length
    if len(B) > 2000:
        B = B[:2000]
    return B

