def compute_n_from_B_bitset(B):
    """
    Efficiently compute n by building a bitset of achievable positive differences.
    Returns 0 if 1 is not achievable.
    """
    if not B:
        return 0
    max_b = max(B)
    max_diff = max_b  # largest possible difference is max(B) - 0
    # bitset as Python int: bit i is 1 if difference i is achievable
    bitset = 0
    B_sorted = sorted(B)
    # Build differences: for each pair (a,b) with a>=b, set bit (a-b)
    # We can use nested loops; short ceilings keep it fast for small B
    for i in range(len(B_sorted)):
        for j in range(len(B_sorted)):
            if i == j:
                continue
            diff = abs(B_sorted[i] - B_sorted[j])
            if diff <= max_diff:
                bitset |= (1 << diff)

    # Check if 1 is achievable
    if not (bitset & 2):  # bit 1 corresponds to value 2 (since bit 0 is diff 0)
        return 0

    # Find largest n such that all diffs 1..n are present
    n = 1
    while (bitset & (1 << n)):
        n += 1
        if n > max_diff:
            break
    return n - 1

